// 为每个依赖生成搜索模式
function getSearchPatterns(dep) {
  const patterns = [
    // 直接 import
    `from ["']${dep}["']`,
    `from ["']${dep}/`,
    `require\\(["']${dep}["']\\)`,
    `require\\(["']${dep}/`,
    // 动态导入
    `import\\(["']${dep}`,
    // 配置文件引用
    `"${dep}"`,
    `'${dep}'`
  ];
  return patterns;
}

function searchInCodebase(dep) {
  const patterns = getSearchPatterns(dep);
  const allMatches = new Set();

  for (const pattern of patterns) {
    try {
      const cmd = `rg -l "${pattern.replace(/"/g, '\\"')}" src/ scripts/ --type ts --type js 2>/dev/null || true`;
      const result = execSync(cmd, { encoding: 'utf8' });
      result.trim().split('\n').filter(f => f).forEach(f => allMatches.add(f));
    } catch (e) {
      // 命令失败但没有找到匹配，继续
    }
  }

  // 特殊检查：tsx 在 package.json scripts 中使用
  if (dep === 'tsx' || dep === 'cross-env') {
    const pkgJson = join(process.cwd(), 'package.json');
    if (existsSync(pkgJson)) {
      const content = readFileSync(pkgJson, 'utf8');
      if (content.includes(dep)) {
        allMatches.add('package.json (scripts)');
      }
    }
  }

  // 特殊检查：typescript 相关
  if (['typescript', '@typescript-eslint/parser', '@typescript-eslint/eslint-plugin', 'typescript-eslint'].includes(dep)) {
    const tsconfig = join(process.cwd(), 'tsconfig.json');
    const eslintConfig = join(process.cwd(), 'eslint.config.js');
    if (existsSync(tsconfig) && readFileSync(tsconfig, 'utf8').includes('typescript')) {
      allMatches.add('tsconfig.json');
    }
    if (existsSync(eslintConfig)) {
      allMatches.add('eslint.config.js');
    }
  }

  // 特殊检查：测试相关
  if (dep === 'vitest') {
    allMatches.add('package.json (scripts)');
  }

  return Array.from(allMatches);
}

console.log('=== 生产依赖 (dependencies) 分析 ===\n');
